var TYPE=require("../../tokenizer").TYPE,IDENT=TYPE.Ident,PLUSSIGN=43,SOLIDUS=47,GREATERTHANSIGN=62,TILDE=126;module.exports={name:"Combinator",structure:{name:String},parse:function(){var e=this.scanner.tokenStart;switch(this.scanner.source.charCodeAt(this.scanner.tokenStart)){case GREATERTHANSIGN:case PLUSSIGN:case TILDE:this.scanner.next();break;case SOLIDUS:this.scanner.next(),this.scanner.tokenType===IDENT&&!1!==this.scanner.lookupValue(0,"deep")||this.error("Identifier `deep` is expected"),this.scanner.next(),this.scanner.isDelim(SOLIDUS)||this.error("Solidus is expected"),this.scanner.next();break;default:this.error("Combinator is expected")}return{type:"Combinator",loc:this.getLocation(e,this.scanner.tokenStart),name:this.scanner.substrToCursor(e)}},generate:function(e){this.chunk(e.name)}};